1721: function Find-CodexProcesses {
1722:     param([datetime]$Since, [string]$Launcher = '', [int]$BridgePid = 0)
1723:     $found = New-Object System.Collections.Generic.List[object]
1724:     $sinceText = $Since.ToString('yyyy-MM-ddTHH:mm:ss', $script:Invariant)
1725:     $byParent = ($script:OnWindows -and $BridgePid -gt 0)
1726:     $rules = if ($byParent) { "children of the interrupted bridge pid $BridgePid" } else { 'name codex*, or a command line containing the recorded launcher or @openai/codex' }
1727:     $previous = $ErrorActionPreference
1728:     $ErrorActionPreference = 'Continue'
1729:     try {
1730:         $procs = New-Object System.Collections.Generic.List[object]
1731:         if ($script:OnWindows) {
1732:             $check = "Win32_Process scan ($rules; started at or after $sinceText)"
1733:             $all = $null
1734:             try { $all = @(Get-CimInstance -ClassName Win32_Process -Property ProcessId, ParentProcessId, Name, CommandLine, CreationDate -ErrorAction Stop) } catch {
1735:                 return [pscustomobject]@{ Found = [object[]]@(); Check = "$check could not run: $(ConvertTo-OneLine $_.Exception.Message)"; Failed = $true }
1736:             }
1737:             foreach ($p in $all) {
1738:                 $procs.Add([pscustomobject]@{ pid = [int]$p.ProcessId; ppid = [int]$p.ParentProcessId; name = [string]$p.Name; cmd = [string]$p.CommandLine; created = $p.CreationDate })
1739:             }
1740:         } else {
1741:             $check = "ps scan ($rules; started at or after $sinceText)"
1742:             $lines = $null
1743:             try { $lines = @(& ps -eo 'pid=,ppid=,etimes=,comm=,args=' 2>$null) } catch { $lines = $null }
1744:             if ($LASTEXITCODE -ne 0 -or $null -eq $lines) {
1745:                 return [pscustomobject]@{ Found = [object[]]@(); Check = "$check could not run"; Failed = $true }
1746:             }
1747:             $now = Get-Date
1748:             foreach ($l in $lines) {
1749:                 $m = [regex]::Match([string]$l, '^\s*(\d+)\s+(\d+)\s+(\d+)\s+(\S+)\s*(.*)$')
1750:                 if (-not $m.Success) { continue }
1751:                 $procs.Add([pscustomobject]@{ pid = [int]$m.Groups[1].Value; ppid = [int]$m.Groups[2].Value; name = $m.Groups[4].Value; cmd = $m.Groups[5].Value; created = $now.AddSeconds( - [double]$m.Groups[3].Value) })
1752:             }
1753:         }
1754:         # never count ourselves or our ancestors (the shell that started this run may
1755:         # carry the launcher path on its command line)
1756:         $byId = @{}
1757:         foreach ($p in $procs) { $byId[$p.pid] = $p }
1758:         $excluded = @{}
1759:         $cur = $PID
1760:         for ($guard = 0; $guard -lt 64 -and $cur -gt 0 -and -not $excluded.ContainsKey($cur); $guard++) {
1761:             $excluded[$cur] = $true
1762:             if (-not $byId.ContainsKey($cur)) { break }
1763:             $cur = $byId[$cur].ppid
1764:         }
1765:         if ($byParent) {
1766:             # A live process holding the bridge's pid now is a reuse (the bridge itself
1767:             # is gone - we hold the lock); its children are not ours, ours predate it.
1768:             $reusedAt = $null
1769:             if ($byId.ContainsKey($BridgePid)) { $reusedAt = $byId[$BridgePid].created }
1770:             foreach ($p in $procs) {
1771:                 if ($excluded.ContainsKey($p.pid) -or $p.ppid -ne $BridgePid) { continue }
1772:                 if ($null -eq $p.created -or $p.created -lt $Since) { continue }
1773:                 if ($null -ne $reusedAt -and $p.created -ge $reusedAt) { continue }
1774:                 $found.Add([pscustomobject]@{ pid = $p.pid; name = $p.name; rule = "child of the interrupted bridge (ppid $BridgePid)" })
1775:             }
1776:         } else {
1777:             foreach ($p in $procs) {
1778:                 if ($excluded.ContainsKey($p.pid)) { continue }
1779:                 if ($null -eq $p.created -or $p.created -lt $Since) { continue }
1780:                 $rule = Get-CodexRule -Name $p.name -Cmd $p.cmd -Launcher $Launcher
1781:                 if ($rule) { $found.Add([pscustomobject]@{ pid = $p.pid; name = $p.name; rule = "$rule, task not verifiable" }) }
