1790: # Decides whether a pending record (from Read-PendingFile) still belongs to a live
1791: # consultation. Returns { Active; Message; Check }:
1792: #   reserved             never active (codex was not started);
1793: #   running / survivors  active while child_pid (with its start time) or any survivor
1794: #                        pid is alive on this host; with pids from another host:
1795: #                        active (they cannot be checked from here);
1796: #   launching            the child may or may not exist: active when
1797: #                        Find-CodexProcesses finds a codex process started since the
1798: #                        record's `started` (or cannot scan); from another host (no
1799: #                        pids to check): treated as dead.
1800: function Test-PendingActive {
1801:     param($Record, [string]$Path)
1802:     $state = [string](Get-PropertyValue $Record 'state' '')
1803:     $recHost = [string](Get-PropertyValue $Record 'host' '')
1804:     $otherHost = [bool]($recHost -and -not $recHost.Equals([Environment]::MachineName, [StringComparison]::OrdinalIgnoreCase))
1805:     $what = "state '$state', consult n=$(Get-PropertyValue $Record 'n' '?'), handoff $(Get-PropertyValue $Record 'nn' '?'), started $(Get-PropertyValue $Record 'started' '?')"
1806:     $launcher = [string](Get-PropertyValue $Record 'launcher' '')
1807:     $pids = New-Object System.Collections.Generic.List[object]
1808:     $cp = 0
1809:     if ([int]::TryParse([string](Get-PropertyValue $Record 'child_pid' ''), [ref]$cp) -and $cp -gt 0) {
1810:         $pids.Add([pscustomobject]@{ pid = $cp; start = (ConvertTo-JsonText (Get-PropertyValue $Record 'child_start_time' '')); name = '' })
1811:     }
1812:     # survivors: { pid, start_time, name } entries; a bare pid (older record) has no
1813:     # start time and is judged by the "looks like codex" rule, never by pid alone.
1814:     foreach ($s in @(Get-PropertyValue $Record 'survivors' @())) {
1815:         $sp = 0
1816:         $sStart = ''
1817:         $sName = ''
1818:         if ($null -ne $s -and $s -is [psobject] -and $s.PSObject.Properties['pid']) {
1819:             [void][int]::TryParse([string]$s.pid, [ref]$sp)
1820:             $sStart = ConvertTo-JsonText (Get-PropertyValue $s 'start_time' '')
1821:             $sName = [string](Get-PropertyValue $s 'name' '')
1822:         } else {
1823:             [void][int]::TryParse([string]$s, [ref]$sp)
1824:         }
1825:         if ($sp -gt 0) { $pids.Add([pscustomobject]@{ pid = $sp; start = $sStart; name = $sName }) }
1826:     }
1827:     $inactive = { param($c) [pscustomobject]@{ Active = $false; Message = ''; Check = $c } }
1828:     $active = { param($m, $c) [pscustomobject]@{ Active = $true; Message = $m; Check = $c } }
1829: 
1830:     if ($state -eq 'reserved') { return (& $inactive 'reserved: codex was never started') }
1831:     if ($pids.Count -gt 0 -and $state -ne 'launching') {
1832:         $pidList = (@($pids | ForEach-Object { $_.pid }) -join ', ')
1833:         if ($otherHost) {
1834:             return (& $active "an interrupted consultation on host $recHost left codex process(es) pid $pidList ($what); they cannot be checked from this host. Delete $Path only after making sure they are gone." "pids on host $recHost")
1835:         }
1836:         $alive = New-Object System.Collections.Generic.List[string]
1837:         $aliveHow = New-Object System.Collections.Generic.List[string]
1838:         $gone = New-Object System.Collections.Generic.List[string]
1839:         foreach ($entry in $pids) {
1840:             $verdict = Test-RecordedProcess -ProcessId $entry.pid -StartTime $entry.start -Name $entry.name -Launcher $launcher
1841:             if ($verdict.Alive) { $alive.Add("$($entry.pid)"); $aliveHow.Add("$($entry.pid) [$($verdict.How)]") } else { $gone.Add("$($entry.pid) [$($verdict.How)]") }
1842:         }
1843:         if ($alive.Count -gt 0) {
1844:             return (& $active "a previous consultation's codex process (pid $($alive -join ', ')) is still running ($what). Wait for it to exit or stop it, then retry; $Path keeps its record until then." "pid $($aliveHow -join ', ') alive")
1845:         }
1846:         # Every RECORDED pid is gone - but the record names the launcher (the npm shim on
1847:         # Windows) and the survivors the kill could see; the real codex may be a
1848:         # descendant that outlived them. A dead launcher is not proof of a dead tree:
1849:         # fall through to the descendant scan below (F04-10).
1850:         $recordedGone = "codex pid(s) $($gone -join ', ') no longer running"
1851:     } else {
1852:         $recordedGone = ''
1853:     }
1854:     # The child may exist unregistered (launching) or as a descendant of a dead recorded
1855:     # process (running/survivors). Scan for it; never trust a dead root or elapsed time.
1856:     if ($otherHost) { return (& $inactive "state '$state' from host $recHost without pids: treated as dead") }
1857:     $since = [datetime]::MinValue
1858:     try { $since = [DateTimeOffset]::Parse((ConvertTo-JsonText (Get-PropertyValue $Record 'started' '')), $script:Invariant).LocalDateTime } catch { $since = [datetime]::MinValue }
1859:     # Parent pids whose (orphaned) children would be ours: the bridge that wrote the
1860:     # record and every recorded codex pid (the launcher shim, the survivors). On Windows
1861:     # an orphan keeps the ParentProcessId of its dead parent; elsewhere orphans are
1862:     # reparented and only the command-line rule below can find them.
1863:     $parentPids = New-Object System.Collections.Generic.List[int]
1864:     $bridgePid = 0
1865:     if ([int]::TryParse([string](Get-PropertyValue $Record 'pid' ''), [ref]$bridgePid) -and $bridgePid -gt 0) { $parentPids.Add($bridgePid) }
1866:     foreach ($entry in $pids) { if ($entry.pid -gt 0 -and -not $parentPids.Contains([int]$entry.pid)) { $parentPids.Add([int]$entry.pid) } }
1867:     $scan = $null
1868:     $checks = New-Object System.Collections.Generic.List[string]
1869:     if ($recordedGone) { $checks.Add($recordedGone) }
1870:     foreach ($parent in $parentPids) {
1871:         $s = Find-CodexProcesses -Since $since -Launcher $launcher -BridgePid $parent
1872:         if ($s.Failed) { $scan = $s; break }
1873:         if (@($s.Found).Count -gt 0) { $scan = $s; break }
1874:         $checks.Add("$($s.Check): none found")
1875:     }
1876:     # The parent-pid rule sees only DIRECT children of a dead parent. If the shim died
1877:     # but its own child lives, only the "looks like codex" rule can see it; its matches
1878:     # cannot be tied to this task and are labelled so. There is deliberately NO age
1879:     # cut-off: an old record with a live codex-looking process started after it refuses
1880:     # until that process exits or the operator deletes the record knowing it is unrelated.
1881:     if ($null -eq $scan -or (-not $scan.Failed -and @($scan.Found).Count -eq 0)) {
1882:         $scan = Find-CodexProcesses -Since $since -Launcher $launcher -BridgePid 0
1883:     }
1884:     if ($checks.Count -gt 0) { $scan.Check = (($checks -join '; ') + '; then ' + $scan.Check) }
1885:     if ($scan.Failed) {
1886:         return (& $active "an interrupted consultation ($what) may have left a codex process running, and the check failed: $($scan.Check). Make sure no such process runs, then delete $Path." $scan.Check)
1887:     }
1888:     if (@($scan.Found).Count -gt 0) {
1889:         $list = (@($scan.Found) | ForEach-Object { "pid $($_.pid) $($_.name) [$($_.rule)]" }) -join ', '
1890:         return (& $active "an interrupted consultation ($what) may still have its codex process running: $list, found by $($scan.Check). Wait for it to exit or stop it, then retry (or delete $Path once you know it is unrelated)." $scan.Check)
1891:     }
1892:     return (& $inactive "$($scan.Check): none found")
1893: }
1894: 
